24	const getBaseUrl = (baseUrl?: string): string => {
25	  if (baseUrl) return baseUrl;
26	  if (typeof window !== 'undefined') {
27	    return window.location.origin;
28	  }
29	  return 'http://localhost:5000';
30	};
