32	export const EndpointUsageModal = ({ open, onClose, endpointName, baseUrl }: EndpointUsageModalProps) => {
33	  const { theme } = useDesignSystemTheme();
34	  const [activeTab, setActiveTab] = useState<'unified' | 'passthrough'>('unified');
35	  const [selectedProvider, setSelectedProvider] = useState<Provider>('openai');
36	  const [selectedLanguage, setSelectedLanguage] = useState<Language>('curl');
37	  const [unifiedLanguage, setUnifiedLanguage] = useState<Language>('curl');
38	  const base = getBaseUrl(baseUrl);
39	  const mlflowInvocationsCurlExample = `curl -X POST ${base}/gateway/${endpointName}/mlflow/invocations \\
40	  -H "Content-Type: application/json" \\
41	  -d '{
42	  "messages": [
43	    {"role": "user", "content": "Hello, how are you?"}
44	  ]
45	}'`;
46	
47	  const mlflowInvocationsPythonExample = `import requests
48	
49	response = requests.post(
50	    "${base}/gateway/${endpointName}/mlflow/invocations",
51	    json={
52	        "messages": [
53	            {"role": "user", "content": "Hello, how are you?"}
54	        ]
55	    }
56	)
57	print(response.json())`;
58	
59	  const openaiChatCurlExample = `curl -X POST ${base}/gateway/mlflow/v1/chat/completions \\
60	  -H "Content-Type: application/json" \\
61	  -d '{
62	  "model": "${endpointName}",
63	  "messages": [
64	    {"role": "user", "content": "How are you?"}
65	  ]
66	}'`;
67	
68	  const openaiChatPythonExample = `from openai import OpenAI
69	
70	client = OpenAI(
71	    base_url="${base}/gateway/mlflow/v1",
72	    api_key="",  # API key not needed, configured server-side
73	)
74	
75	messages = [{"role": "user", "content": "How are you?"}]
76	
77	response = client.chat.completions.create(
78	    model="${endpointName}",  # Endpoint name as model
79	    messages=messages,
80	)
81	print(response.choices[0].message)`;
82	
83	  const openaiPassthroughCurlExample = `curl -X POST ${base}/gateway/openai/v1/responses \\
84	  -H "Content-Type: application/json" \\
85	  -d '{
86	  "model": "${endpointName}",
87	  "input": "How are you?"
88	}'`;
89	
90	  const openaiPassthroughPythonExample = `from openai import OpenAI
91	
92	client = OpenAI(
93	    base_url="${base}/gateway/openai/v1",
94	    api_key="dummy",  # API key not needed, configured server-side
95	)
96	
97	response = client.responses.create(
98	    model="${endpointName}",
99	    input="How are you?",
100	)
101	print(response.output_text)`;
102	
103	  const anthropicPassthroughCurlExample = `curl -X POST ${base}/gateway/anthropic/v1/messages \\
