122	    max_tokens=1024,
123	    messages=[{"role": "user", "content": "How are you?"}],
124	)
125	print(response.content[0].text)`;
126	
127	  const geminiPassthroughCurlExample = `curl -X POST ${base}/gateway/gemini/v1beta/models/${endpointName}:generateContent \\
128	  -H "Content-Type: application/json" \\
129	  -d '{
130	  "contents": [{
131	    "parts": [{"text": "How are you?"}]
132	  }]
133	}'`;
