511	export async function fetchOrFail(input: RequestInfo | URL, options?: RequestInit): Promise<Response> {
512	  let cookieString = '';
513	  if (typeof document !== 'undefined' && typeof document.cookie === 'string') {
514	    cookieString = document.cookie || '';
515	  }
516	
517	  const fetchOptions: RequestInit = {
518	    ...options,
519	    headers: {
520	      ...getDefaultHeaders(cookieString),
521	      ...options?.headers,
522	    },
