import { useMutation } from '@mlflow/mlflow/src/common/utils/reactQueryHooks';
import { fetchOrFail } from '@mlflow/mlflow/src/common/utils/FetchUtils';
import { NetworkRequestError } from '@databricks/web-shared/errors';

export interface TryItError {
  message: string;
  responseBody?: string;
}

export interface UseTryItOptions {
  tryItRequestUrl: string;
}

export interface UseTryItResult {
  data: string | undefined;
  error: TryItError | undefined;
  isLoading: boolean;
  sendRequest: (body: string) => void;
  reset: () => void;
}

/**
 * Pretty-print a raw response body string as JSON when possible, falling back to the
 * original text if it cannot be parsed.
 */
const prettyPrintJson = (text: string): string => {
  try {
    return JSON.stringify(JSON.parse(text), null, 2);
  } catch {
    return text;
  }
};

/**
 * Hook that manages sending a POST request to the given URL and tracking the response
 * data, error, and loading state for the endpoint usage "Try it" panel.
 *
 * Uses react-query's `useMutation` (so a QueryClientProvider is required) together with
 * `fetchOrFail` to perform the request.
 */
export const useTryIt = ({ tryItRequestUrl }: UseTryItOptions): UseTryItResult => {
  const [data, setData] = useState<string | undefined>(undefined);
  const [error, setError] = useState<TryItError | undefined>(undefined);

  const mutation = useMutation<void, unknown, string>({
    mutationFn: async (body: string) => {
      setData(undefined);
      setError(undefined);

      let parsedBody: unknown;
      try {
        parsedBody = JSON.parse(body);
      } catch {
        setError({ message: 'Invalid JSON in request body' });
        return;
      }

      try {
        const response = await fetchOrFail(tryItRequestUrl, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(parsedBody),
        });
        const text = await response.text();
        setData(prettyPrintJson(text));
      } catch (e) {
        if (e instanceof NetworkRequestError && e.response) {
          let responseBody: string | undefined;
          try {
            responseBody = prettyPrintJson(await e.response.text());
          } catch {
            responseBody = undefined;
          }
          setError({ message: e.message, responseBody });
        } else if (e instanceof Error) {
          setError({ message: e.message });
        } else {
          setError({ message: 'An unexpected error occurred.' });
        }
      }
    },
  });

  const sendRequest = useCallback(
    (body: string) => {
      mutation.mutate(body);
    },
    [mutation],
  );

  const reset = useCallback(() => {
    setData(undefined);
    setError(undefined);
  }, []);

  return {
    data,
    error,
    isLoading: mutation.isLoading,
    sendRequest,
    reset,
  };
};
