const getBaseUrl = (baseUrl?: string): string => {
  if (baseUrl) return baseUrl;
  if (typeof window !== 'undefined') {
    return window.location.origin;
  }
  return 'http://localhost:5000';
};

const prettyBody = (value: unknown): string => JSON.stringify(value, null, 2);

const TryItPanel = ({ requestUrl, defaultBody }: { requestUrl: string; defaultBody: string }) => {
  const { theme } = useDesignSystemTheme();
  const intl = useIntl();
  const [body, setBody] = useState(defaultBody);
  const { data, error, isLoading, sendRequest, reset } = useTryIt({ tryItRequestUrl: requestUrl });

  const handleReset = () => {
    setBody(defaultBody);
    reset();
  };

  return (
    <div css={{ display: 'flex', flexDirection: 'column', gap: theme.spacing.md }}>
      <div css={{ display: 'flex', flexDirection: 'column', gap: theme.spacing.xs }}>
        <Typography.Text bold>
          <FormattedMessage defaultMessage="Request" description="Try it request section label" />
        </Typography.Text>
        <TextArea
          componentId="mlflow.gateway.usage-modal.try-it-request-body"
          value={body}
          onChange={(e) => setBody(e.target.value)}
          autoSize={{ minRows: 6, maxRows: 16 }}
          aria-label={intl.formatMessage({
            defaultMessage: 'Request body',
            description: 'Try it request body input label',
          })}
        />
      </div>

      <div css={{ display: 'flex', gap: theme.spacing.sm }}>
        <Button
          componentId="mlflow.gateway.usage-modal.send-request"
          type="primary"
          onClick={() => sendRequest(body)}
          loading={isLoading}
          disabled={isLoading}
        >
          <FormattedMessage defaultMessage="Send request" description="Try it send request button" />
        </Button>
        <Button componentId="mlflow.gateway.usage-modal.reset-example" onClick={handleReset} disabled={isLoading}>
          <FormattedMessage defaultMessage="Reset example" description="Try it reset example button" />
        </Button>
      </div>

      <div css={{ display: 'flex', flexDirection: 'column', gap: theme.spacing.xs }}>
        <Typography.Text bold>
          <FormattedMessage defaultMessage="Response" description="Try it response section label" />
        </Typography.Text>
        {isLoading && <Spinner />}
        {!isLoading && error && (
          <Alert
            componentId="mlflow.gateway.usage-modal.try-it-error"
            type="error"
            message={error.message}
            description={
              error.responseBody ? (
                <CodeSnippet
                  language="text"
                  theme={theme.isDarkMode ? 'duotoneDark' : 'light'}
                  style={{ fontSize: theme.typography.fontSizeSm }}
                >
                  {error.responseBody}
                </CodeSnippet>
              ) : undefined
            }
            closable={false}
          />
        )}
        {!isLoading && !error && data && (
          <CodeSnippet
            language="text"
            theme={theme.isDarkMode ? 'duotoneDark' : 'light'}
            style={{
              fontSize: theme.typography.fontSizeSm,
              padding: `${theme.spacing.sm}px ${theme.spacing.md}px`,
            }}
          >
            {data}
          </CodeSnippet>
        )}
      </div>
    </div>
  );
};

